mapper.select:
SELECT EXISTS (
    SELECT 1
      FROM entry_qrs
     WHERE reservation_id = #{reservationId}
)

mapper.update:
UPDATE entry_qrs
   SET available_from = #{availableFrom}
     , expires_at = #{expiresAt}
     , updated_at = #{now}
 WHERE reservation_id = #{reservationId}

mapper.insert:
INSERT INTO entry_qrs (
       reservation_id
     , token_hash
     , qr_status
     , available_from
     , expires_at
     , issued_at
     , revoked_at
     , revoke_reason
     , created_at
     , updated_at
) VALUES (
       #{reservationId}
     , #{tokenHash}
     , NULL
     , #{availableFrom}
     , #{expiresAt}
     , #{now}
     , NULL
     , NULL
     , #{now}
     , #{now}
)

INSERT INTO entry_records (
       fair_id
     , reservation_id
     , user_id
     , entry_source
     , first_checked_in_at
     , last_scanned_at
     , scan_count
     , first_processed_by
     , first_gate_name
     , created_at
     , updated_at
) VALUES (
       #{fairId}
     , #{reservationId}
     , #{userId}
     , #{entrySource}
     , #{checkedInAt}
     , #{checkedInAt}
     , 1
     , #{processedBy}
     , #{gateName}
     , #{checkedInAt}
     , #{checkedInAt}
)

mapper.update:
UPDATE entry_records
   SET last_scanned_at = #{scannedAt}
     , scan_count = scan_count + 1
     , updated_at = #{scannedAt}
 WHERE entry_record_id = #{entryRecordId}

UPDATE reservations
   SET status = 'CHECKED_IN'
     , updated_at = #{now}
 WHERE reservation_id = #{reservationId}
   AND status = 'CONFIRMED'

mapper.insert:
INSERT INTO entry_scan_logs (
       entry_qr_id
     , reservation_id
     , fair_id
     , scan_type
     , result_code
     , scanned_at
     , processed_by
     , gate_name
     , device_info
     , created_at
) VALUES (
       #{entryQrId}
     , #{reservationId}
     , #{fairId}
     , 'GATE'
     , #{resultCode}
     , #{scannedAt}
     , #{processedBy}
     , #{gateName}
     , #{deviceInfo}
     , #{scannedAt}
)
